from pathlib import Path
import base64, gzip

p=Path("index.html")
s=p.read_text(encoding="utf-8")
mark="HLGB v91.59 RECUPERACAO DE FALTAS + SEPARACAO X PRODUCAO"
if mark in s:
    print("v91.59 already applied")
    raise SystemExit(0)

old="""function projectionOpenMissingQty(order,item){
 const oid=String(order?.id??'').trim();
 const pid=String(item?.productId??'').trim();
 if(!oid||!pid)return 0;
 return (db.missingPieces||[]).reduce((sum,m)=>{
   if(String(m?.orderId??'').trim()!==oid)return sum;
   if(String(m?.productId??'').trim()!==pid)return sum;
   if(String(m?.issueType||'Peça faltante')!=='Peça faltante')return sum;
   return sum+Math.max(0,+m?.remainingQty||0);
 },0);
}
"""
new="""function projectionOpenMissingQty(order,item){
 const oid=String(order?.id??'').trim();
 const pid=String(item?.productId??'').trim();
 if(!oid||!pid)return 0;
 return (db.missingPieces||[]).reduce((sum,m)=>{
   if(String(m?.orderId??'').trim()!==oid)return sum;
   if(String(m?.productId??'').trim()!==pid)return sum;
   if(String(m?.issueType||'Peça faltante')!=='Peça faltante')return sum;
   const allocated=(Array.isArray(m?.history)?m.history:[]).reduce((a,h)=>{
     const q=Math.max(0,+h?.qty||0),dest=String(h?.destination||'');
     if(dest==='finishedPieces')return a+q;
     if(dest==='clientInvoice')return a+Math.max(0,q-Math.max(0,+h?.projectionAppliedQty||0));
     return a;
   },0);
   return sum+Math.max(0,+m?.remainingQty||0)+allocated;
 },0);
}
"""
if s.count(old)!=1:
    raise SystemExit(f"projectionOpenMissingQty target: expected 1, found {s.count(old)}")
s=s.replace(old,new,1)

payload=""
addon=gzip.decompress(base64.b64decode(payload)).decode("utf-8")
if "</body>" not in s:
    raise SystemExit("closing body not found")
head,tail=s.rsplit("</body>",1)
s=head+addon+"\n</body>"+tail

s=s.replace("v91.58 Multiusuário","v91.59 Multiusuário")
s=s.replace("Versão v91.58","Versão v91.59")
s=s.replace(">v91.58<",">v91.59<")
s=s.replace("const VER955='91.58';","const VER955='91.59';",1)
s=s.replace("Segurança de gravação v91.58","Segurança de gravação v91.59")

p.write_text(s,encoding="utf-8")
print("v91.59 missing delivery + separation/production rules applied")
